### 1. Core Firmware (C++17)

```cpp
// -------------------------------------------------------------
// File : temp_log_esp32.cpp
// Architecture : ESP32 (Arduino‑Framework 2.0.x)
// Compiler : gcc 12.2 (ESPCreated)
// -------------------------------------------------------------
#include <Arduino.h>
#include <Wire.h>
#include <NTPClient.h>
#include <WiFi.h>
#include <WiFiUdp.h>

// ---------- Configuration ----------
#ifndef WIFI_SSID
  #error "Define WIFI_SSID macro before compile."
#endif
#ifndef WIFI_PASS
  #error "Define WIFI_PASS macro before compile."
#endif
#define TEMP_ADC_PIN    34          // ADC1_CHANNEL_6 (ESP32‑S2/3: 34)
#define TEMP_ADC_ATTEN  ADC_11db    // Full range 0‑3.3V → 4096 counts
#define SAMPLE_RATE_MS 500         // 2 Hz sampling
#define CALIBRATION_POINTS 5
#define I2C_SCL_PIN    22
#define I2C_SDA_PIN    21

// ---------- Data Structures ----------
struct TempSample {
  uint32_t epoch;      // Unix seconds (UTC)
  int16_t  raw_adc;    // 12‑bit ADC count (0‑4095)
  int16_t  temp_c_int; // Temperature *100 (e.g., 2350 = 23.5 °C)
};

// ---------- Calibration Data (empirical) ----------
static const int16_t cal_raw[CALIBRATION_POINTS] = { 1024, 2048, 3072, 4095, 0 };
static const int16_t cal_temp[CALIBRATION_POINTS] = {    0,  250,  500,  750, 1000 }; // *100 °C

// ---------- Helper Functions ----------
inline float lin_interp(int16_t x, int16_t x0, int16_t x1,
                        int16_t y0, int16_t y1) {
  return y0 + (y1 - y0) * (static_cast<float>(x - x0) / (x1 - x0));
}

int16_t adc_to_temp(int16_t adc) {
  // Simple linear interpolation on pre‑measured calibration points.
  // If adc < min(cal_raw) → extrapolate using first segment.
  if (adc <= cal_raw[0])   return cal_temp[0];
  if (adc >= cal_raw[CALIBRATION_POINTS-1]) return cal_temp[CALIBRATION_POINTS-1];

  for (uint8_t i = 0; i < CALIBRATION_POINTS-1; ++i) {
    if (adc >= cal_raw[i] && adc <= cal_raw[i+1]) {
      return static_cast<int16_t>(lin_interp(adc,
                                             cal_raw[i],   cal_raw[i+1],
                                             cal_temp[i],   cal_temp[i+1]));
    }
  }
  return -9999; // Should never reach here.
}

// ---------- WiFi / NTP ----------
WiFiUDP ntpUDP;
NTPClient timeClient(ntpUDP, "pool.ntp.org", 0, 60000); // UTC, 60 s update

void initWiFi() {
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
  }
  timeClient.begin();
  timeClient.update();
}

// ---------- I2C Slave for PC readout ----------
void i2c_slave_setup() {
  Wire.begin(I2C_SDA_PIN, I2C_SCL_PIN);
  Wire.onRequest([]() {
    static uint8_t seq = 0;
    // Push one sample per request (max 32 bytes)
    TempSample s;
    s.epoch = timeClient.getEpochTime();
    analogReadResolution(12);
    s.raw_adc = analogRead(TEMP_ADC_PIN);
    s.temp_c_int = adc_to_temp(s.raw_adc);
    Wire.write((uint8_t*)&s, sizeof(TempSample));
    seq++;
  });
}

// ---------- Main Loop ----------
void setup() {
  Serial.begin(115200);
  analogReadResolution(12);
  analogSetAtten(TEMP_ADC_PIN, TEMP_ADC_ATTEN);
  initWiFi();
  i2c_slave_setup();

  // Initial calibration sanity check
  for (uint8_t i = 0; i < CALIBRATION_POINTS; ++i) {
    Serial.printf_P("CAL[%u] raw=%" PRId16 " temp=%" PRId16 "\n", i,
                    cal_raw[i], cal_temp[i]);
  }
}

void loop() {
  static uint32_t last_ms = 0;
  if (millis() - last_ms >= SAMPLE_RATE_MS) {
    last_ms = millis();
    timeClient.update();

    TempSample samp;
    samp.epoch = timeClient.getEpochTime();
    samp.raw_adc = analogRead(TEMP_ADC_PIN);
    samp.temp_c_int = adc_to_temp(samp.raw_adc);

    // Log to UART (CSV)
    Serial.printf("%lu,%" PRId16 ",%" PRId16 "\n",
                  samp.epoch, samp.raw_adc, samp.temp_c_int);
  }
}
