% MATLAB - M4A1 SOPMOD Block II External Ballistics
% Environmental Conditions: Sea Level Standard, 29.53" Hg, 59°F, 50% RH

function [trajectory_data] = m4a1_trajectory(angle_deg, velocity_fps, distance_yards)
    % Constants
    g = 32.1738;  % gravitational acceleration ft/s²
    rho_air = 0.0023769;  % slugs/ft³ (sea level)

    % Projectile Properties
    m = 62/7000;  % mass in slugs (62 grains to lbs to slugs)
    Cd = 0.325;   % drag coefficient (from BC conversion)
    A = pi*(0.224/24)^2;  % frontal area ft²

    % Drag Function (G7 model approximation)
    drag_force = @(v) 0.5 * rho_air * v^2 * Cd * A;

    % Numerical Integration (4th Order Runge-Kutta)
    dt = 0.001;  % time step
    t = 0:dt:10;  % time vector

    % Initial Conditions
    angle_rad = deg2rad(angle_deg);
    vx = velocity_fps * cos(angle_rad);
    vy = velocity_fps * sin(angle_rad);
    x = 0; y = 0;

    trajectory_x = [];
    trajectory_y = [];
    velocity_mag = [];

    for i = 1:length(t)
        % Store current state
        trajectory_x(end+1) = x * 3;  % convert feet to yards
        trajectory_y(end+1) = y;
        velocity_mag(end+1) = sqrt(vx^2 + vy^2);

        % Acceleration components with drag
        v_total = sqrt(vx^2 + vy^2);
        if v_total > 0
            ax = (-drag_force(v_total) * vx/v_total) / m;
            ay = (-g - drag_force(v_total) * vy/v_total) / m;
        else
            ax = 0; ay = -g;
        end

        % Update velocities (Runge-Kutta would go here for precision)
        vx = vx + ax * dt;
        vy = vy + ay * dt;

        % Update positions
        x = x + vx * dt;
        y = y + vy * dt;

        % Termination condition
        if y < 0 && i > 1
            break;
        end
    end

    trajectory_data = [trajectory_x', trajectory_y', velocity_mag'];
end
