#include "soc/gpio_struct.h"
#include "soc/gpio_reg.h"

// Direct register access for GPIO27 toggle
static inline void gpio27_toggle_direct(void) {
    // Method 1: Using enable_w1ts/enable_w1tc for direction control
    GPIO.enable_w1ts = (1 << 27);   // Set GPIO27 as output

    // Method 2: Direct OUT register manipulation
    uint32_t current_state = GPIO.out;
    GPIO.out = current_state ^ (1 << 27);  // XOR toggle

    // Alternative: Using W1TS/W1TC registers for atomic operations
    if (current_state & (1 << 27)) {
        GPIO.out_w1tc = (1 << 27);  // Clear bit
    } else {
        GPIO.out_w1ts = (1 << 27);  // Set bit
    }
}

// High-speed GPIO write with precise timing control
static inline void gpio_write_atomic(uint8_t pin, uint8_t state) {
    if (state) {
        GPIO.out_w1ts = (1 << pin);
    } else {
        GPIO.out_w1tc = (1 << pin);
    }
}
