## 3. I²S Configuration Script (16kHz, 32-bit, PDM-decimated)

```c
#include "soc/i2s_struct.h"
#include "soc/dport_reg.h"
#include "driver/dma_types.h"
#include "esp_attr.h"

// Clock tree: PLL_CLK (80MHz APB) → I2S_CLKM_DIV_NUM = 4 → 20MHz I2S clock
// PCM bit clock = 20MHz / (32+32) = 312.5 kHz → sample rate = 312.5kHz / 16 = 19,531 Hz
// Actual achievable: 16000 Hz with divisor = 5 → bitclock = 4MHz, fs = 62.5kHz / 4 = 15,625 Hz (closest)

static void i2s_gpio_init(void) {
    gpio_config_t io_conf = {
        .pin_bit_mask = (1 << I2S_WS_PIN) | (1 << I2S_BCK_PIN) | (1 << I2S_DATA_PIN),
        .mode         = GPIO_MODE_INPUT,
        .pull_up_en   = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type    = GPIO_INTR_DISABLE
    };
    gpio_config(&io_conf);
    // Configure GPIO matrix — I2S0 uses GPIO matrix (0-31 offset = direct connect)
    gpio_matrix_in(I2S_DATA_PIN,    I2S0I_DATA_IN0_IDX,  false);
    gpio_matrix_in(I2S_BCK_PIN,     I2S0I_BCK_IN_IDX,   false);
    gpio_matrix_in(I2S_WS_PIN,      I2S0I_WS_IN_IDX,    false);
}

static void i2s_hw_init(void) {
    // 1. Enable APB clock gate
    DPORT_SET_PERI_REG_MASK(DPORT_PERIP_CLK_EN_REG, DPORT_I2S_CLK_EN);
    DPORT_CLEAR_PERI_REG_MASK(DPORT_PERIP_RST_EN_REG, DPORT_I2S_RST);

    // 2. Configure sample rate: MCLK = 80MHz / (clkm_div_num) / (div_a / div_b)
    I2S0.clkm_conf.clkm_div_a   = 1;   // Divider A (1-63)
    I2S0.clkm_conf.clkm_div_b   = 0;   // Divider B (0-63)
    I2S0.clkm_conf.clkm_div_num = 4;   // Integer divisor (1-63) → MCLK = 80MHz/4 = 20MHz
    I2S0.clkm_conf.clk_en       = 1;
    I2S0.clkm_conf.clk_sel      = 1;   // 1 = PLL_CLK (80MHz)

    // 3. Configure I²S format: Philips MSB-first, 32-bit slot width
    I2S0.conf.rx_slave_mod      = 0;   // Master mode
    I2S0.conf.rx_big_endian     = 0;
    I2S0.conf.rx_binary        = 1;   // MSB-first
    I2S0.conf.rx_ws_width       = 32;  // WS pulse = 1 bit clock
    I2S0.conf.rx_ws_inv        = 0;
    I2S0.conf.rx_clk_sel       = 2;   // I2S_CLK (from clkm)

    // 4. RX mode configuration
    I2S0.rx_conf1.rx_bit_start  = 7;   // MSB position (32b: start=31, but PDM sends 16b LSB)
    I2S0.rx_conf1.rx_msb_shift  = 0;   // Philips standard (no right-shift)
    I2S0.rx_conf1.rx_dma_equal  = 0;   // Sample on BCK rising edge

    // 5. Configure 32-bit wide mode (32 slots, 16 bits each L+R)
    I2S0.rx_conf2.rx_bits_mod   = 32;  // Total bits per channel slot
    I2S0.rx_conf2.rx mono_fsm_en = 0;
    I2S0.rx_conf2.rx_pcm_conf   = 0;   // PCM mode disabled (I²S standard)

    // 6. RX filter — reject glitches < 4 I2S clocks
    I2S0.rx_filter.rx_filter_en = 1;
    I2S0.rx_filter.rx_filter    = 3;   // 3-clock debounce

    // 7. DMA configuration
    I2S0.dma_conf.rx_fifo_reset = 1;   // Reset FIFO
    I2S0.dma_conf.rx_fifo_reset = 0;
    I2S0.dma_conf.rx_dscr_en    = 1;    // Enable DMA descriptors
    I2S0.dma_conf.rx_eof_mode   = 1;    // EOF when DMA pops last data
    I2S0.dma_conf.rx_data_len   = SAMPLES_PER_BUFFER * BYTES_PER_SAMPLE;
    I2S0.dma_conf.rx_eof_en     = 1;    // Generate EOF interrupt on buffer complete

    // 8. Enable RX
    I2S0.conf.rx_start = 1;
    I2S0.conf.rx_update = 1;            // Latch configuration
    I2S0.conf.rx_update = 0;
}

static void i2s_dma_link_init(lldesc_s *dma_desc, uint8_t *buf_a, uint8_t *buf_b) {
    // Descriptor A → Buffer A
    dma_desc[0].eof     = 0;
    dma_desc[0].owner   = 1;            // DMA owns descriptor
    dma_desc[0].data_len = SAMPLES_PER_BUFFER * BYTES_PER_SAMPLE;
    dma_desc[0].buf_len  = SAMPLES_PER_BUFFER * BYTES_PER_SAMPLE;
    dma_desc[0].buf_addr = (uint32_t)buf_a;
    dma_desc[0].next_desc = (uint32_t)&dma_desc[1];

    // Descriptor B → Buffer B
    dma_desc[1].eof     = 1;            // Last descriptor — triggers EOF interrupt
    dma_desc[1].owner   = 1;
    dma_desc[1].data_len = SAMPLES_PER_BUFFER * BYTES_PER_SAMPLE;
    dma_desc[1].buf_len  = SAMPLES_PER_BUFFER * BYTES_PER_SAMPLE;
    dma_desc[1].buf_addr = (uint32_t)buf_b;
    dma_desc[1].next_desc = (uint32_t)&dma_desc[0]; // Loop back to A

    // Start RX DMA link
    I2S0.in_link.start       = 0;
    I2S0.in_link.addr       = (uint32_t)&dma_desc[0] & 0xFFFF;
    I2S0.in_link.start       = 1;
}
