### **V. QUATERNION-BASED ORIENTATION ESTIMATION**

#### **V.1 Complementary Filter with Madgwick Update**

```cpp
// attitude_estimation.cpp
typedef struct {
    float q0, q1, q2, q3;  // Quaternion components
    float-beta;            // Filter tuning parameter
} quaternion_state_t;

void madgwick_update(float gx, float gy, float gz,
                     float ax, float ay, float az,
                     float bx, float by, float bz,
                     float dt) {

    // Compute feedback gradient
    float fc[3];
    fc[0] = ay*bz - az*By;
    fc[1] = az*Bx - ax*bz;
    fc[2] = ax*by - ay*Bx;

    // Apply feedback to integrate
    float half_beta = 0.5f * state.beta;
    q1_dot = -0.5f*gx*q0 - half_beta*fc[0];
    q2_dot = -0.5f*gy*q0 - half_beta*fc[1];
    q3_dot = -0.5f*gz*q0 - half_beta*fc[2];
    q0_dot =  0.5f*gx*q1 + 0.5f*gy*q2 + 0.5f*gz*q3;

    // Euler integration
    q0 += q0_dot * dt;
    q1 += q1_dot * dt;
    q2 += q2_dot * dt;
    q3 += q3_dot * dt;

    // Normalize quaternion
    float norm = sqrt(q0*q0 + q1*q1 + q2*q2 + q3*q3);
    q0 /= norm; q1 /= norm; q2 /= norm; q3 /= norm;
}
```

