// Calculate optimal transmit power based on current link quality
float get_transmit_power(uint8_t rssi_dbm) {
    if (rssi_dbm <= 0) return 0.0f;
    // Inverse logarithmic mapping: higher RSSI → lower power
    float normalized = (100.0f - rssi_dbm) / 90.0f;  // clamp to [0,1]
    return transmit_power_table[normalized * sizeof(float)];
}

