    uint8_t  msg_type;        // 0=heartbeat, 1=data, 2=control
    uint8_t  payload[256];    // Variable-length payload
    uint32_t seq_num;         // Sequence number for ACK tracking
} MeshPacket;

// Forward a packet through the mesh network
bool forward_packet(MeshPacket& pkt) {
    uint8_t dest = next_hop[nodes[0].node_id];  // Simplified: direct neighbor

    // Check rate limit
    static uint32_t sent_count = 0;
    if (sent_count >= RATE_LIMIT) {
        delay(1);  // Brief backoff
        sent_count = 0;
    }

    // Apply power control
    float power = get_transmit_power(pkt.rssi);
    uint8_t tx_enable = (power > 0) ? 1 : 0;

    // Build outgoing packet
    pkt.msg_type = 1;  // DATA
    pkt.payload[0] = pkt.seq_num;
    memcpy(pkt.payload+1, pkt.payload, sizeof(pkt.payload));

    // Configure radio parameters
    WiFi_MAC_CTRL_RADIO_FREQ = WIFI_MAC_CTRL_RADIO_FREQ_2G;
    WiFi_MAC_CTRL_TX_POWER = power;
    WiFi_MAC_CTRL_BAND = WIFI_MAC_CTRL_BAND_2;  // 2.4 GHz

    // Send via Wi-Fi (primary) or BT (fallback)
    if (WiFi_connect_status() == WL_CONNECTED) {
        WiFi_mac_addr_t addr = get_local_ipv4();
        WiFi_send_packet(&pkt, addr, true);
        return true;
    } else {
        // Fallback to Bluetooth LE
        bt_send_packet(&pkt, "bt://local_node");
        return true;
    }
}

// Heartbeat mechanism with exponential backoff on failure
void send_heartbeat() {
    Node* self = &nodes[node_counter];
    self->last_seen = millis();
    self->active = true;

    // Broadcast heartbeat to all neighbors
    for (int i = 0; i < MAX_NODES; i++) {
        if (i != node_counter && nodes[i].active) {
            MeshPacket hb;
            hb.msg_type = 0;  // HEARTBEAT
            hb.payload[0] = node_counter;
            forward_packet(hb);
        }
    }

    // Exponential backoff if no ACK received within HEARTBEAT_INTERVAL
    static uint32_t last_ack_time = 0;
    if ((millis() - last_ack_time) > HEARTBEAT_INTERVAL * 2) {
        // Re-send after timeout
        forward_packet(MeshPacket{0, {}, 0});
    }
}
