def bit_load_distribution(nodes):
    """
    Distribute traffic load proportionally to each node's capacity.
    Uses Shannon-Hartley theorem constraint.
    """
    capacities = [0.85, 0.78, 0.92, 0.65, 0.88, 0.70, 0.76, 0.81, 0.74, 0.89]  # [MB/s]
    total_capacity = sum(capacities)

