    angle = np.deg2rad(angle_deg)
    v = v0
    x = 0.0
    y = 0.0
    vx = v0 * np.cos(angle)
    vy = v0 * np.sin(angle)

    # Choose Cd tables
    if cd_model == 'G1':
        mach = Mach_G1
        cd = Cd_G1
    else:
        mach = Mach_G7
        cd = Cd_G7

    # Storage
    xs = [x]
    ys = [y]
    vs = [v]
    thetas = [angle]

    for i in range(steps):
        # Interpolate Cd at current speed
        mach_curr = v / a0
        Cd = cd_at_velocity(v, mach, cd)

        # Geometry
        A = np.pi * (diameter/2.0)**2

        # Drag force magnitude
        Fd = 0.5 * rho * v**2 * Cd * A

        # Accelerations
        ax_drag = - (Fd / mass) * (vx / v) if v != 0 else 0.0
        ay_drag = - (Fd / mass) * (vy / v) if v != 0 else 0.0

        ax_total = ax_drag
        ay_total = ay_drag - g

        # Update velocities
        vx += ax_total * dt
        vy += ay_total * dt
        v = np.hypot(vx, vy)

        # Update position
        x += vx * dt
        y += vy * dt

        # Store
        xs.append(x)
        ys.append(y)
        vs.append(v)
        thetas.append(np.arctan2(vy, vx))

        # Stop if projectile hits ground (y < 0)
        if y < 0.0:
            break

    return np.array(xs), np.array(ys), np.array(vs), np.array(thetas)
```

