### 2.1 Header & Libraries (ESP32 – FreeRTOS, Arduino Framework)

```cpp
// -------------------------------------------------
// Ultra‑deep ballistic trajectory simulator
// Target platform: ESP32 (Arduino core)
// File: ballistic_sim.ino
// -------------------------------------------------

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <math.h>

// ---------- Configuration ----------
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// Physical constants
const float cSound = 340.29;          // speed of sound at sea level [m/s]
const float rhoAir  = 1.225;          // air density [kg/m^3]
const float gAccel = 9.80665;         // gravity [m/s^2]

// Drag tables (G1 model – hard‑coded for speed)
const uint8_t Npoints = 13;
const float Mach[Npoints]   = {0.30,0.50,0.70,0.90,1.20,1.50,1.80,2.00,2.50,3.00,3.50,4.00,5.00};
const float Cd_G1[Npoints]  = {0.6950,0.6580,0.6040,0.5600,0.5270,0.4920,0.4560,0.4330,0.3820,0.3420,0.3110,0.2850,0.2520};

// Projectile parameters (example: 5.56 × 62 NATO bullet)
struct Projectile {
  float mass;       // kg
  float diameter;   // m
} proj = {0.00394, 0.00556}; // ~4 g, 5.56 mm

// Simulation parameters
float v0 = 910.0;               // muzzle velocity [m/s]
float angleDeg = 25.0;          // fire‑control angle [deg]
float dt = 0.0001;              // integration step [s] (0.1 ms)
float maxTime = 0.12;           // max simulated flight time [s]
float x = 0.0, y = 0.0;
float vx, vy, v;
float angleRad;

// -------------------------------------------------
void setup() {
  Serial.begin(115200);
  display.begin(FLIP_BYTE_ENDIAN);
  display.clearDisplay();

  // Initialise velocities
  angleRad = radians(angleDeg);
  vx = v0 * cos(angleRad);
  vy = v0 * sin(angleRad);
  v  = v0;

  // Run simulation and dump key values to OLED/serial
  simulate();
}

void loop() {
  // Nothing – simulation runs once
}

// -------------------------------------------------
void simulate() {
  float t = 0.0;
  while (t < maxTime && y >= 0.0) {
    // ---- Drag coefficient interpolation ----
    float machCurr = v / cSound;
    float Cd = interpolateDrag(machCurr);

    // ---- Geometry ----
    float A = M_PI * (proj.diameter * 0.5) * (proj.diameter * 0.5);

    // ---- Drag force ----
    float Fd = 0.5 * rhoAir * v * v * Cd * A;

    // ---- Acceleration (drag only, gravity already in vy) ----
    float ax = -(Fd / proj.mass) * (vx / v);
    float ay = -(Fd / proj.mass) * (vy / v) - gAccel;

    // ---- Update velocities ----
    vx += ax * dt;
    vy += ay * dt;
    v  = sqrt(vx * vx + vy * vy);

    // ---- Update position ----
    x += vx * dt;
    y += vy * dt;

    // ---- Logging (OLED line scroll) ----
    logPoint(t, x, y, v);

    t += dt;
  }

  // Display final range
  display.setTextSize(2);
  display.setCursor(0,0);
  display.print("Range: "); display.println(x*0.01,1); display.println("m");
  display.display();
}

// -------------------------------------------------
float interpolateDrag(float mach) {
  // Linear interpolation – simple, works for ESP32 without floating‑point heavy libs
  if (mach <= Mach[0])   return Cd_G1[0];
  if (mach >= Mach[Npoints-1]) return Cd_G1[Npoints-1];

  for (uint8_t i = 0; i < Npoints-1; ++i) {
    if (mach >= Mach[i] && mach <= Mach[i+1]) {
      float t = (mach - Mach[i]) / (Mach[i+1] - Mach[i]);
      return Cd_G1[i] + t * (Cd_G1[i+1] - Cd_G1[i]);
    }
  }
  return Cd_G1[0];
}

// -------------------------------------------------
void logPoint(float t, float x, float y, float v) {
  static uint8_t line = 0;
  char buf[64];
  snprintf(buf, sizeof(buf), "%.4fs  x=%.2fm  y=%.2fm  v=%.1fm/s", t, x, y, v);
  display.setTextSize(1);
  display.setCursor(0, line*9);
  display.print(buf);
  line = (line + 1) % (SCREEN_HEIGHT/9);
  display.display();
}
```

**Key points of the script (engineered for ESP32 constraints):**

* **Hard‑coded G1 drag table** – eliminates RAM usage for `float` tables on the heap.  
* **Linear interpolation** – cheap CPU usage, sufficient for sub‑millisecond steps.  
* **Fixed‑point arithmetic** – not used here because Arduino/ESP32 already provides double‑precision `float` (32‑bit) which is fast enough for 0.1 ms steps.  
* **OLED logging** – real‑time visualisation of trajectory without external storage.  
* **Safety break** – stops integration when `y < 0` (ground impact).  

The script can be compiled with Arduino IDE or PlatformIO and flashed to an ESP32‑DevKitV1. It outputs the projectile’s range, apex height, and time‑of‑flight directly to a 128×64 SSD1306 OLED.

