#define BIT_DEPTH_BITS          16
#define CHANNEL_COUNT            2
#define DMA_BUFFER_COUNT         4       // Each half = double-buffer
#define DMA_BUFFER_SAMPLES      (SAMPLE_RATE_HZ * 10 / 1000) // 10ms blocks
#define DMA_BUFFER_BYTES        (DMA_BUFFER_SAMPLES * BIT_DEPTH_BITS / 8 * CHANNEL_COUNT)
#define DMA_DESC_COUNT           DMA_BUFFER_COUNT
#define CACHE_LINE_SIZE         64
#define ALIGNED_BUFFER_SIZE     (((DMA_BUFFER_BYTES + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE) * CACHE_LINE_SIZE)

// Memory region - must be DRAM, not flash-mapped
static DRAM_ATTR uint8_t  audio_buffer_a[ALIGNED_BUFFER_SIZE] __attribute__((aligned(64)));
static DRAM_ATTR uint8_t  audio_buffer_b[ALIGNED_BUFFER_SIZE] __attribute__((aligned(64)));

// DMA descriptor ring
static DRAM_ATTR dma_desc_t dma_descriptors[DMA_DESC_COUNT];

// Synchronization primitives
static QueueHandle_t dma_done_queue;
static volatile uint32_t active_buffer_index = 0;
