// ═══════════════════════════════════════════════════════════════════════
struct i2s_reg_config_t {
    uint32_t reg_offset;
    uint32_t reg_value;
    const char* description;
};

static const i2s_reg_config_t I2S_TX_INIT_SEQUENCE[] = {
    // Conf1: Enable TX, reset TX FIFO
    { I2S_TX_CONF_REG,        0x00000001, "TX_SOFT_RESET" },
    { I2S_TX_CONF_REG,        0x00000000, "TX_CONF_CLEAR" },

    // Conf2: MSB shift, Philips I2S standard
    { I2S_TX_CONF2_REG,       0x00000000, "TX_STANDARD_MODE" },

    // Clkm div: 160MHz / 4 = 40MHz base, then / (sample_rate × 2 × channels)
    { I2S_CLKM_CONF_REG,      0x00090003, "CLK_DIV: mst_div=3, clkm_div_num=9" },

    // FIFO mode: 16-bit data width, tx_16bit_queue_en
    { I2S_TX_FIFO_MOD_REG,    0x00000002, "TX_FIFO_MOD_16BIT" },

    // Sample rate: tx_bck_div_num controls WS frequency
    { I2S_TX_CONF1_REG,       0x0000003F, "TX_DATA_BIT_NUM=32, TX_TOTAL_BIT_NUM=32" },

    // Conf: Enable I2S, TX master mode, MSB first
    { I2S_TX_CONF_REG,        0x000000C1, "TX_ENABLE | TX_SLAVE_MOD=0 | TX_MSB_SHIFT" },

    // DMA configuration
    { I2S_LC_CONF_REG,        0x11000001, "AHB_FIFO_EN | DMA_RESET_FSM" },
    { I2S_OUT_LINK_REG,       0x00000000, "OUTLINK_STOP" },
};

static const size_t I2S_REG_INIT_COUNT = sizeof(I2S_TX_INIT_SEQUENCE) / sizeof(i2s_reg_config_t);

// ═══════════════════════════════════════════════════════════════════════
// HARDWARE INITIALIZATION SEQUENCE
// ═══════════════════════════════════════════════════════════════════════
static esp_err_t i2s_hw_init(void)
{
    // 1. Enable I2S peripheral clock
    periph_module_enable(PERIPH_I2S0_MODULE);
    periph_module_reset(PERIPH_I2S0_MODULE);

    // 2. Apply register initialization sequence
    for (size_t i = 0; i < I2S_REG_INIT_COUNT; i++) {
        *((volatile uint32_t*)(I2S0_BASE + I2S_TX_INIT_SEQUENCE[i].reg_offset)) = 
            I2S_TX_INIT_SEQUENCE[i].reg_value;
    }

    // 3. Configure I2S pins via GPIO matrix
    //    GPIO 22 = BCLK, GPIO 25 = WS, GPIO 26 = DOUT
    gpio_config_t io_conf = {
        .pin_bit_mask = (1ULL << 22) | (1ULL << 25) | (1ULL << 26),
        .mode         = GPIO_MODE_OUTPUT,
        .pull_up_en   = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type    = GPIO_INTR_DISABLE,
    };
    gpio_config(&io_conf);

    // 4. Route I2S signals through GPIO matrix
    //    I2S0O_BCK_OUT -> GPIO22, I2S0O_WS_OUT -> GPIO25, I2S0O_DATA_OUT0 -> GPIO26
    gpio_matrix_out(22, I2S0O_BCK_OUT_IDX, 0, 0);
    gpio_matrix_out(25, I2S0O_WS_OUT_IDX,  0, 0);
    gpio_matrix_out(26, I2S0O_DATA_OUT0_IDX, 0, 0);

    return ESP_OK;
}

// ═══════════════════════════════════════════════════════════════════════
// DMA DESCRIPTOR INITIALIZATION
// ═══════════════════════════════════════════════════════════════════════
static void dma_descriptors_init(void)
{
    uint8_t* buffer_ptrs[DMA_BUFFER_COUNT] = {
        audio_buffer_a,
        audio_buffer_b,
        audio_buffer_a,  // Reuse - demonstrates circular nature
        audio_buffer_b,
    };

    for (int i = 0; i < DMA_DESC_COUNT; i++) {
        dma_descriptors[i].buffer   = (uint32_t)buffer_ptrs[i];
        dma_descriptors[i].dma_len = ALIGNED_BUFFER_SIZE;
        dma_descriptors[i].length  = ALIGNED_BUFFER_SIZE;
        dma_descriptors[i].offset  = 0;
        dma_descriptors[i].owner   = 1;  // CPU owns initially
        dma_descriptors[i].eof     = 1;  // Trigger interrupt on completion
        dma_descriptors[i].sub_sof = 0;

        // Link to next descriptor (circular)
        if (i < DMA_DESC_COUNT - 1) {
            dma_descriptors[i].next = (dma_desc_t*)&dma_descriptors[i + 1];
        } else {
            dma_descriptors[i].next = (dma_desc_t*)&dma_descriptors[0]; // Circular wrap
        }
    }

    // Set DMA outlink start address
    *((volatile uint32_t*)(I2S0_BASE + I2S_OUT_LINK_REG)) = 
        (uint32_t)&dma_descriptors[0] & 0xFFFFF;
}

// ═══════════════════════════════════════════════════════════════════════
// INTERRUPT SERVICE ROUTINE
// ═══════════════════════════════════════════════════════════════════════
static void IRAM_ATTR i2s_isr_handler(void* arg)
{
    // Clear DMA outlink done interrupt
    I2S0.int_clr.out_done = 1;

    // Determine which buffer just completed
    // Read from hardware: eof_descraddr contains address of completed descriptor
    uint32_t completed_desc_addr = I2S0.eof_descr_addr;
    uint32_t desc_index = (completed_desc_addr - (uint32_t)dma_descriptors) / sizeof(dma_desc_t);

    // Calculate which buffer (mod 2 because we have 2 logical double-buffers)
    uint32_t completed_buffer = desc_index % 2;

    // Send to queue for application processing
    BaseType_t higher_priority_task_woken = pdFALSE;
    uint32_t msg = completed_buffer;
    xQueueSendFromISR(dma_done_queue, &msg, &higher_priority_task_woken);

    if (higher_priority_task_woken) {
        portYIELD_FROM_ISR();
    }
}

// ═══════════════════════════════════════════════════════════════════════
// INTERRUPT ENABLE SEQUENCE
// ═══════════════════════════════════════════════════════════════════════
static esp_err_t i2s_interrupt_enable(void)
{
    // 1. Allocate interrupt
    esp_err_t err = esp_intr_alloc(
        ETS_I2S0_INTR_SOURCE,          // Interrupt source
        ESP_INTR_FLAG_IRAM |            // Must stay in IRAM
        ESP_INTR_FLAG_LEVEL3 |          // High priority
        ESP_INTR_FLAG_SHARED,           // Can share with others
        i2s_isr_handler,
        NULL,
        &i2s_intr_handle
    );
    if (err != ESP_OK) return err;

    // 2. Enable outlink-done interrupt in I2S controller
    I2S0.int_ena.out_done = 1;

    // 3. Configure DMA for circular mode, auto-restart
    I2S0.lc_conf.out_rst        = 1;  // Reset OUT DMA FSM
    I2S0.lc_conf.out_rst        = 0;
    I2S0.lc_conf.out_loop_test  = 0;
    I2S0.lc_conf.out_auto_wrback= 1;  // Auto-set EOF when done
    I2S0.lc_conf.outdscr_burst_en = 1;
    I2S0.lc_conf.outdscr_addr_bURST_EN = 1;

    return ESP_OK;
}

// ═══════════════════════════════════════════════════════════════════════
// DMA START SEQUENCE
// ═══════════════════════════════════════════════════════════════════════
static void dma_start_transfer(void)
{
    // 1. Reset outlink
    I2S0.out_link.stop = 1;
    I2S0.out_link.start = 0;

    // 2. Clear outlink done
    I2S0.int_clr.out_done = 1;

    // 3. Set starting descriptor address
    I2S0.out_link.addr = ((uint32_t)&dma_descriptors[0]) & 0xFFFFF;

    // 4. Start DMA transfer
    I2S0.out_link.stop = 0;
    I2S0.out_link.start = 1;

    // 5. Start I2S TX
    I2S0.tx_conf.tx_start = 1;
}

// ═══════════════════════════════════════════════════════════════════════
// BUFFER FILLING FUNCTION (Called from application task)
// ═══════════════════════════════════════════════════════════════════════
static void fill_audio_buffer_sine(uint8_t* buffer, size_t byte_count, 
                                     float frequency_hz, float amplitude)
{
    const float two_pi_f = 2.0f * 3.14159265358979f * frequency_hz / SAMPLE_RATE_HZ;
    const int16_t max_amplitude = (int16_t)(32767.0f * amplitude);

    int16_t* sample_ptr = (int16_t*)buffer;
    size_t sample_count = byte_count / sizeof(int16_t);

    // Per-channel sine wave (interleaved stereo)
    for (size_t i = 0; i < sample_count; i += CHANNEL_COUNT) {
        int16_t sample_value = (int16_t)(max_amplitude * sinf(two_pi_f * i));

        // Left channel
        sample_ptr[i] = sample_value;
        // Right channel (identical for mono test)
        sample_ptr[i + 1] = sample_value;
    }
}

// ═══════════════════════════════════════════════════════════════════════
// AUDIO PROCESSING TASK
// ═══════════════════════════════════════════════════════════════════════
static void audio_processing_task(void* pvParameters)
{
    uint32_t completed_buffer;
    uint8_t* buffers[2] = { audio_buffer_a, audio_buffer_b };
    uint32_t current_fill_buffer = 0;

    // Pre-fill both buffers before starting
    fill_audio_buffer_sine(audio_buffer_a, ALIGNED_BUFFER_SIZE, 440.0f, 0.5f);
    fill_audio_buffer_sine(audio_buffer_b, ALIGNED_BUFFER_SIZE, 440.0f, 0.5f);

    // Hand ownership of first buffer to DMA (owner = 2)
    dma_descriptors[0].owner = 2;
    dma_descriptors[1].owner = 2;

    // Start DMA transfer
    dma_start_transfer();

    while (1) {
        // Wait for DMA to complete a buffer
        if (xQueueReceive(dma_done_queue, &completed_buffer, portMAX_DELAY) == pdTRUE) {

            // At this point, completed_buffer contains the index of the buffer
            // that DMA just finished processing. We can now safely fill it.

            // Safety: Re-claim ownership from DMA
            size_t desc_idx = completed_buffer % 2; // Map buffer to its descriptor
            dma_descriptors[desc_idx].owner = 1;    // CPU reclaims ownership

            // FILL THE BUFFER WITH NEW AUDIO DATA HERE
            // In this example: alternate between 440Hz and 880Hz sine
            float freq = (current_fill_buffer % 2 == 0) ? 440.0f : 880.0f;
            fill_audio_buffer_sine(buffers[completed_buffer], 
                                   ALIGNED_BUFFER_SIZE, freq, 0.5f);

            // Log buffer completion
            uint32_t timestamp = esp_timer_get_time();
            ets_printf("[%lu us] Buffer %lu completed, refilling with %.1f Hz\n",
                       timestamp, completed_buffer, freq);

            // Re-give ownership to DMA
            dma_descriptors[desc_idx].owner = 2;

            current_fill_buffer++;
        }
    }
}

