### 4. ESP32‑Based Barrel Temperature Logger (C++/Arduino)

```cpp
// File: barrel_temp_logger.ino
// Platform: ESP32‑DevKitC
// Sensor: DS18B20 (OneWire) – Part # DS18B20‑EF
// Sampling: 1 Hz, 30‑second averaging, 24 h auto‑shutdown
// Output: CSV to SD (filename: BARREL_YYMMDD_HHMMSS.csv)

#include <OneWire.h>
#include <DallasTemperature.h>
#include <SD.h>
#include <SPI.h>
#include <TimeLib.h>

#define ONE_WIRE_BUS 4
#define SD_CS_PIN 5

OneWire oneWire(ONE_WIRE_BUS);
DallasTemperature sensors(&oneWire);

// Barrel thermal model constants
const float alpha = 1.2e-5;          // linear expansion coeff (1/K)
const float L0 = 300.0;              // nominal barrel length (mm)
const float k_thermal = 45.0;        // W/(m·K) – for later power calculations
const float c_p = 0.49e3;            // J/(kg·K) – specific heat

float avgTemp = 0.0;
unsigned long sampleCount = 0;
bool logging = true;

File dataFile;

void setup() {
  Serial.begin(115200);
  sensors.begin();
  sensors.setResolution(12); // 12‑bit (≈0.0625°C)

  // SD init
  SPI.begin();
  if (!SD.begin(SD_CS_PIN)) {
    Serial.println("SD init failed");
    logging = false;
    return;
  }

  // Create CSV file
  String filename = "BARREL_" + getDateTime() + ".csv";
  dataFile = SD.open(filename.c_str(), FILE_WRITE);
  if (!dataFile) {
    Serial.println("Failed to open file");
    logging = false;
    return;
  }
  dataFile.println("Timestamp_s,Temperature_C,AvgTemp_C,DeltaL_mm,Expansion_Pct");
}

void loop() {
  if (!logging) return;

  // Read temperature (average over 5 reads)
  float sum = 0.0;
  for (int i = 0; i < 5; i++) {
    sensors.requestTemperatures();
    float t = sensors.getTempCByIndex(0);
    if (t > -50 && t < 150) sum += t;
    delay(20);
  }
  float rawTemp = sum / 5.0;

  // Simple moving average (30 samples = 30 s)
  static float tempHistory[30];
  static int idx = 0;
  tempHistory[idx] = rawTemp;
  avgTemp = 0.0;
  for (int i = 0; i < 30; ++i) avgTemp += tempHistory[i];
  avgTemp /= 30;
  idx = (idx + 1) % 30;

  // Barrel length change
  float deltaT = avgTemp - 20.0; // reference 20 °C
  float deltaL = L0 * alpha * deltaT; // mm

  // Log
  unsigned long now = millis() / 1000;
  dataFile.print(now);
  dataFile.print(',');
  dataFile.print(rawTemp, 4);
  dataFile.print(',');
  dataFile.print(avgTemp, 4);
  dataFile.print(',');
  dataFile.print(deltaL, 5);
  dataFile.print(',');
  dataFile.println((deltaL / L0) * 100, 6);
  dataFile.flush();

  // Optional: stop after 24 h
  static unsigned long startTime = millis();
  if (millis() - startTime > 86400000UL) {
    dataFile.close();
    Serial.println("24 h complete – file saved.");
    logging = false;
  }

  delay(1000);
}

